// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0) && target != address(c));
        vm.deal(address(this), 1 ether);

        // Fund the contract so it has some balance
        (bool success, ) = address(c).call{value: 0.5 ether}("");
        require(success, "funding failed");

        uint256 balanceBefore = address(c).balance;

        // Drive through sendMoney which triggers receive
        c.sendMoney(target, value);

        uint256 balanceAfter = address(c).balance;

        // The contract balance should never increase after a sendMoney call
        // because any ether sent to a non-reverting receive function should
        // either be forwarded to target or trigger depositsCount++ without
        // increasing balance
        assertTrue(balanceAfter <= balanceBefore);
    }
}

